async function loadAnalytics(){const startInput=$('#analyticsStart'),endInput=$('#analyticsEnd');if(!startInput||!endInput)return;if(!startInput.value){$('#analyticsPreset').value='7';setAnalyticsPreset()}const startValue=startInput.value,endValue=endInput.value;if(!startValue||!endValue||startValue>endValue)throw new Error('Escolha um intervalo de datas válido.');const out=$('#analyticsMessage');$('#analyticsDownload').disabled=true;msg(out,'Carregando métricas…');const data=await analyticsQuery(startValue,endValue);analyticsData=data;analyticsPreviousData=null;analyticsRecommendations=[];analyticsPeriod={start:startValue,end:endValue};$('#analyticsVisits').textContent=Number(data.visits||0).toLocaleString('pt-BR');$('#analyticsVisitors').textContent=Number(data.unique_visitors||0).toLocaleString('pt-BR');$('#analyticsConversion').textContent=`${Number(data.conversion_rate||0).toLocaleString('pt-BR',{maximumFractionDigits:1})}%`;$('#analyticsAbandoned').textContent=Number(data.abandoned_carts||0).toLocaleString('pt-BR');$('#analyticsPaidOrders').textContent=Number(data.paid_orders||0).toLocaleString('pt-BR');$('#analyticsSales').textContent=money(data.sales||0);renderAnalyticsSeries(data.series);renderAnalyticsList('#analyticsSources',data.traffic_sources,'source','visits',value=>Number(value||0).toLocaleString('pt-BR'));renderAnalyticsList('#analyticsProducts',data.top_products,'name','views',value=>`${Number(value||0).toLocaleString('pt-BR')} visualizações`);const preset=$('#analyticsPreset').value,monthly=preset==='month_to_date'||preset==='previous_month';$('#analyticsMonthlyPanel').hidden=!monthly;if(monthly){const previousStart=shiftDateByMonth(startValue,-1),previousEnd=preset==='previous_month'?dateKey(new Date(new Date(`${previousStart}T12:00:00`).getFullYear(),new Date(`${previousStart}T12:00:00`).getMonth()+1,0)):shiftDateByMonth(endValue,-1);analyticsPreviousData=await analyticsQuery(previousStart,previousEnd);analyticsRecommendations=renderMonthlyInsights(data,analyticsPreviousData)}$('#analyticsDownload').disabled=false;msg(out,'')}
