function downloadAnalyticsCsv(data,period,previous,recommendations,filename){const rows=[['Relatório de estatísticas e vendas',`${period.start} a ${period.end}`],[],['Indicador','Resultado'],['Visitas',data.visits||0],['Visitantes únicos',data.unique_visitors||0],['Conversão',`${Number(data.conversion_rate||0).toLocaleString('pt-BR',{maximumFractionDigits:1})}%`],['Carrinhos abandonados',data.abandoned_carts||0],['Pedidos pagos',data.paid_orders||0],['Vendas confirmadas',money(data.sales||0)]];if(previous){rows.push([],['Comparação com o período anterior','Período selecionado','Período anterior'],['Visitas',data.visits||0,previous.visits||0],['Conversão',`${Number(data.conversion_rate||0).toLocaleString('pt-BR',{maximumFractionDigits:1})}%`,`${Number(previous.conversion_rate||0).toLocaleString('pt-BR',{maximumFractionDigits:1})}%`],['Vendas',money(data.sales||0),money(previous.sales||0)],['Carrinhos abandonados',data.abandoned_carts||0,previous.abandoned_carts||0]);rows.push([],['Pontos para acompanhar']);(recommendations||[]).forEach(tip=>rows.push([tip]))}rows.push([],['Visitas e vendas por dia','Visitas','Vendas']);(data.series||[]).forEach(day=>rows.push([day.date,day.visits||0,money(day.sales||0)]));rows.push([],['Origem do tráfego','Visitas']);(data.traffic_sources||[]).forEach(source=>rows.push([source.source,source.visits]));rows.push([],['Produtos mais vistos','Visualizações']);(data.top_products||[]).forEach(product=>rows.push([product.name||product.slug,product.views]));const csv='\uFEFF'+rows.map(row=>row.map(reportCell).join(';')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
