$('#newKitBtn')?.addEventListener('click',()=>openKitGroupEditor());$('#newSingleKitBtn')?.addEventListener('click',()=>openKitEditor());$('#kitVariantType')?.addEventListener('change',e=>{kitVariantType=e.currentTarget.value;editingKitVariants.forEach(v=>{if(kitVariantType==='beer_quantity'){v.beerQuantity=Number(v.beerQuantity)||1;const beer=v.components.find(c=>c.component_type==='beer');if(beer)beer.quantity=v.beerQuantity}else v.volume=Number(v.volume)||300});renderKitVariants()});$('#addKitVariant')?.addEventListener('click',()=>{const components=editingKitVariants[0]?.components?.map(c=>({...c}))||kitComponentDefaults();const beerQuantity=kitVariantType==='beer_quantity'?nextKitBeerQuantity():1;if(kitVariantType==='beer_quantity'){const beer=components.find(c=>c.component_type==='beer');if(beer)beer.quantity=beerQuantity}editingKitVariants.push({volume:'',beerQuantity,price:'',active:true,sort_order:kits.length+editingKitVariants.length+1,components});renderKitVariants()});$('#closeKitDialog')?.addEventListener('click',()=>kitDlg.close());kitDlg?.addEventListener('click',e=>{if(e.target===kitDlg)kitDlg.close()});$('#addKitComponent')?.addEventListener('click',()=>{editingKitComponents.push({component_type:'inventory',quantity:1,unit_cost:0});renderKitComponents();updateKitFinancials()});
