function stockLabel(s){return s==='sold_out'?'Esgotado':s==='low_stock'?'Últimas unidades':'Em estoque'}function price(v){return v==null?'Preço sob consulta':Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function beerImage(src){if(!src)return '/assets/favicon.png';const value=String(src).trim();if(/^https?:\/\//i.test(value)||value.startsWith('data:')||value.startsWith('blob:')||value.startsWith('/'))return value;return '/'+value.replace(/^\.\//,'').replace(/^\.\.\//,'')}
function setBeerImage(img,src){img.src=beerImage(src);img.addEventListener('error',()=>{if(!img.dataset.fallback){img.dataset.fallback='1';img.src='/assets/favicon.png'}},{once:true})}
function beerRow(b,mini=false){const row=document.createElement('div');row.className=mini?'mini-row':'beer-row';const img=document.createElement('img');setBeerImage(img,b.image_url);img.alt='';const info=document.createElement('div');info.className='beer-row-info';const h=document.createElement('h4');h.textContent=b.title||b.name;const p=document.createElement('p');p.textContent=`${b.style||'Estilo não informado'} · ${b.volume||'Volume não informado'} · ${price(b.price)}`;info.append(h,p);if(!mini){const label=document.createElement('label');label.className='check fridge-toggle';const toggle=document.createElement('input');toggle.type='checkbox';toggle.checked=b.featured===true;toggle.setAttribute('aria-label','Mostrar na geladeira: '+(b.title||b.name));label.append(toggle,document.createTextNode(' Mostrar na geladeira'));info.append(label);toggle.addEventListener('change',async()=>{const selected=toggle.checked;toggle.disabled=true;try{if(selected&&b.active){const rows=await req('/rest/v1/beers?select=id&featured=eq.true&active=eq.true');if(rows.filter(x=>x.id!==b.id).length>=8)throw new Error('A geladeira comporta 8 rótulos. Desmarque outro antes de adicionar este.');}await req('/rest/v1/beers?id=eq.'+encodeURIComponent(b.id),{method:'PATCH',body:{featured:selected},headers:{Prefer:'return=minimal'}});b.featured=selected;msg(appMsg,'Seleção da geladeira salva.','success');}catch(err){toggle.checked=b.featured===true;msg(appMsg,err.message,'error');}finally{toggle.disabled=false;}});}if(!mini){const specs=document.createElement('div');specs.className='beer-admin-specs';[['Cervejaria',b.brewery],['ABV',b.abv]].forEach(([label,value])=>{const item=document.createElement('span');item.innerHTML=`<b>${label}:</b> ${value||'Não informado'}`;specs.append(item)});info.append(specs)}const badge=document.createElement('span');badge.className='badge';badge.textContent=b.active?stockLabel(b.stock_status):'Inativo';row.append(img,info,badge);if(!mini){const btn=document.createElement('button');btn.className='edit-btn';btn.textContent='Editar';btn.addEventListener('click',()=>openEditor(b));row.append(btn)}return row}
function renderBeers(){const q=$('#beerSearch').value.trim().toLowerCase(),list=$('#beerList');list.replaceChildren();beers.filter(b=>!q||`${b.title} ${b.name} ${b.brewery} ${b.brand}`.toLowerCase().includes(q)).forEach(b=>list.append(beerRow(b)))}$('#beerSearch').addEventListener('input',renderBeers);
function renderRecent(){const el=$('#recentBeers');el.replaceChildren();beers.slice(0,5).forEach(b=>el.append(beerRow(b,true)))}
function money(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function orderStatusLabel(v){return {awaiting_payment:'Aguardando pagamento',paid:'Pago',preparing:'Separando',ready:'Pronto',out_for_delivery:'Saiu para entrega',completed:'Concluído',cancelled:'Cancelado'}[v]||v||'Novo'}
function paymentLabel(v){return {pending:'Pendente',paid:'Pago',failed:'Falhou',refunded:'Estornado'}[v]||v||'Pendente'}
async function loadOrders(){orders=await req('/rest/v1/orders?select=*,order_items(*)&order=created_at.desc&limit=100');$('#statOrders').textContent=orders.length;const paid=orders.filter(o=>o.payment_status==='paid');$('#statPaid').textContent=paid.length;$('#statRevenue').textContent=money(paid.reduce((sum,o)=>sum+Number(o.total||0),0));const el=$('#ordersList');el.replaceChildren();if(!orders.length){const p=document.createElement('p');p.className='muted';p.textContent='Nenhum pedido registrado no banco ainda.';el.append(p);return}orders.forEach(o=>{const r=document.createElement('button');r.type='button';r.className='order-row order-card';const main=document.createElement('div');const code=document.createElement('strong');code.textContent=o.order_code||o.id.slice(0,8);const customer=document.createElement('span');customer.textContent=`${o.customer_name||'Cliente'} · ${new Date(o.created_at).toLocaleString('pt-BR')}`;main.append(code,customer);const amount=document.createElement('strong');amount.className='order-amount';amount.textContent=money(o.total);const pay=document.createElement('span');pay.className=`badge payment-${o.payment_status||'pending'}`;pay.textContent=paymentLabel(o.payment_status);const status=document.createElement('span');status.className='badge';status.textContent=orderStatusLabel(o.status);r.append(main,amount,pay,status);r.addEventListener('click',()=>openOrder(o));el.append(r)})}
$('#refreshOrders')?.addEventListener('click',()=>loadOrders().catch(err=>msg(appMsg,err.message,'error')));
const orderDlg=$('#orderDialog');
function detailLine(label,value){const row=document.createElement('div');const a=document.createElement('span');a.textContent=label;const b=document.createElement('strong');b.textContent=value||'—';row.append(a,b);return row}
function openOrder(o){currentOrder=o;$('#orderTitle').textContent=o.order_code||'Pedido';$('#orderStatus').value=o.status||'awaiting_payment';const detail=$('#orderDetail');detail.replaceChildren();const info=document.createElement('div');info.className='order-info-grid';info.append(detailLine('Cliente',o.customer_name),detailLine('WhatsApp',o.customer_phone),detailLine('E-mail',o.customer_email),detailLine('Recebimento',o.delivery_type==='delivery'?'Entrega':'Retirada'),detailLine('Pagamento',paymentLabel(o.payment_status)),detailLine('Total',money(o.total)));detail.append(info);if(o.delivery_address){const address=o.delivery_address;detail.append(detailLine('Endereço',[address.street,address.number,address.district].filter(Boolean).join(', ')))}if(o.notes)detail.append(detailLine('Observações',o.notes));const items=document.createElement('div');items.className='order-items-detail';const h=document.createElement('h4');h.textContent='Itens';items.append(h);(o.order_items||[]).forEach(i=>{const row=document.createElement('div');const n=document.createElement('span');n.textContent=`${i.quantity}× ${i.beer_name_snapshot}`;const t=document.createElement('strong');t.textContent=money(i.line_total);row.append(n,t);items.append(row)});detail.append(items);msg($('#orderMsg'),'');orderDlg.showModal()}
$('#closeOrderDialog')?.addEventListener('click',()=>orderDlg.close());orderDlg?.addEventListener('click',e=>{if(e.target===orderDlg)orderDlg.close()});
$('#saveOrderStatus')?.addEventListener('click',async()=>{if(!currentOrder)return;try{await req(`/rest/v1/orders?id=eq.${encodeURIComponent(currentOrder.id)}`,{method:'PATCH',body:{status:$('#orderStatus').value,updated_at:new Date().toISOString()},headers:{Prefer:'return=minimal'}});msg($('#orderMsg'),'Status atualizado.','success');await loadOrders();currentOrder=orders.find(o=>o.id===currentOrder.id)||currentOrder}catch(err){msg($('#orderMsg'),err.message,'error')}});
function eventImage(src){if(!src)return '/assets/compartilhamento-de-link.jpg';const v=String(src).trim();if(/^https?:\/\//i.test(v)||v.startsWith('data:')||v.startsWith('blob:')||v.startsWith('/'))return v;return '/'+v.replace(/^\.\//,'').replace(/^\.\.\//,'')}
function formatEventDate(v,end){if(!v)return 'Data a confirmar';const a=new Date(v+'T12:00:00');if(Number.isNaN(a.getTime()))return 'Data a confirmar';if(!end||end===v)return a.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});const b=new Date(end+'T12:00:00');if(Number.isNaN(b.getTime()))return a.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});return `${a.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})} a ${b.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}`}
async function loadEvents(){events=await req('/rest/v1/events?select=*&order=event_date.asc,sort_order.asc');renderAdminEvents()}
function renderAdminEvents(){const list=$('#eventsAdminList');if(!list)return;list.replaceChildren();if(!events.length){const p=document.createElement('p');p.className='muted';p.textContent='Nenhum evento cadastrado ainda.';list.append(p);return}events.forEach(ev=>{const row=document.createElement('div');row.className='event-admin-row';const img=document.createElement('img');img.src=eventImage(ev.image_url);img.alt='';const info=document.createElement('div');info.className='event-admin-info';const h=document.createElement('h4');h.textContent=ev.title||'Evento';const d=document.createElement('p');d.textContent=`${formatEventDate(ev.event_date,ev.event_end_date)} · ${ev.location||'Local a confirmar'}`;const l=document.createElement('p');l.textContent=ev.purchase_url?'Ingresso com link de compra':'Sem link de compra';info.append(h,d,l);const badge=document.createElement('span');badge.className='badge';badge.textContent=ev.active!==false?'Publicado':'Inativo';const edit=document.createElement('button');edit.type='button';edit.className='edit-btn';edit.textContent='Editar';edit.addEventListener('click',()=>openEventEditor(ev));row.append(img,info,badge,edit);list.append(row)})}
const eventDlg=$('#eventDialog');
function openEventEditor(ev=null){$('#eventForm').reset();val('#eventId',ev?.id);val('#eTitle',ev?.title);val('#eDate',ev?.event_date);val('#eEndDate',ev?.event_end_date);val('#eLocation',ev?.location);val('#ePurchaseUrl',ev?.purchase_url);val('#eInstagram',ev?.instagram_handle?('@'+String(ev.instagram_handle).replace(/^@/,'')):'');val('#eSort',ev?.sort_order??events.length+1);val('#eDescription',ev?.description);$('#eActive').checked=ev?.active!==false;$('#deactivateEventBtn').hidden=!ev;$('#eventEditorTitle').textContent=ev?'Editar evento':'Novo evento';$('#eventImagePreview').removeAttribute('src');if(ev?.image_url)$('#eventImagePreview').src=eventImage(ev.image_url);msg($('#eventEditorMsg'),'');eventDlg.showModal()}
$('#newEventBtn')?.addEventListener('click',()=>openEventEditor());$('#closeEventDialog')?.addEventListener('click',()=>eventDlg.close());eventDlg?.addEventListener('click',e=>{if(e.target===eventDlg)eventDlg.close()});$('#eImage')?.addEventListener('change',()=>{const f=$('#eImage').files[0];if(f)$('#eventImagePreview').src=URL.createObjectURL(f)});
async function uploadEventImage(file){if(!file)return null;if(file.size>5*1024*1024)throw new Error('A imagem ultrapassa 5 MB.');const ext=(file.name.split('.').pop()||'webp').toLowerCase();const path=`evento-${Date.now()}.${ext}`;await req(`/storage/v1/object/event-images/${encodeURIComponent(path)}`,{method:'POST',body:file,headers:{'Content-Type':file.type||'application/octet-stream','x-upsert':'false'}});return `${URL}/storage/v1/object/public/event-images/${path}`}
$('#eventForm')?.addEventListener('submit',async e=>{e.preventDefault();const out=$('#eventEditorMsg');msg(out,'Salvando…');try{const id=$('#eventId').value||null;let image=id?events.find(x=>x.id===id)?.image_url:null;const file=$('#eImage').files[0];if(file)image=await uploadEventImage(file);const start=$('#eDate').value,end=$('#eEndDate').value||null;if(end&&end<start)throw new Error('A data final não pode ser anterior à data inicial.');const instagram=$('#eInstagram').value.trim().replace(/^@/,'').replace(/^https?:\/\/(www\.)?instagram\.com\//i,'').replace(/\/.*$/,'');const body={title:$('#eTitle').value.trim(),event_date:start,event_end_date:end,location:$('#eLocation').value.trim(),purchase_url:$('#ePurchaseUrl').value.trim()||null,instagram_handle:instagram||null,description:$('#eDescription').value.trim(),image_url:image,active:$('#eActive').checked,sort_order:Number($('#eSort').value)||0,updated_at:new Date().toISOString()};if(id)await req(`/rest/v1/events?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body,headers:{Prefer:'return=minimal'}});else await req('/rest/v1/events',{method:'POST',body,headers:{Prefer:'return=minimal'}});await loadEvents();msg(out,'Evento salvo e publicado na agenda.','success');setTimeout(()=>eventDlg.close(),650)}catch(err){msg(out,err.message,'error')}});
$('#deactivateEventBtn')?.addEventListener('click',async()=>{const id=$('#eventId').value;if(!id)return;try{await req(`/rest/v1/events?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:{active:false,updated_at:new Date().toISOString()},headers:{Prefer:'return=minimal'}});await loadEvents();eventDlg.close();msg(appMsg,'Evento desativado.','success')}catch(err){msg($('#eventEditorMsg'),err.message,'error')}});
let partyItems=[];
function renderPartyItems(){const box=$('#partyItemsEditor');box.replaceChildren();if(!partyItems.length){const p=document.createElement('p');p.className='muted';p.textContent='Nenhum item cadastrado ainda.';box.append(p)}partyItems.forEach((value,i)=>{const row=document.createElement('div');row.className='party-item-row';const input=document.createElement('input');input.type='text';input.maxLength=140;input.value=value;input.placeholder='Ex.: equipamento, montagem, copos';input.setAttribute('aria-label',`Item incluso ${i+1}`);input.addEventListener('input',()=>partyItems[i]=input.value);const del=document.createElement('button');del.type='button';del.className='secondary';del.textContent='Remover';del.addEventListener('click',()=>{partyItems.splice(i,1);renderPartyItems()});row.append(input,del);box.append(row)})}
function renderPartyImages(){const box=$('#partyGalleryEditor');box.replaceChildren();partyImages.forEach((item,i)=>{const card=document.createElement('article');card.className='party-image-card';const img=document.createElement('img');img.src=item.preview||item.image_url;img.alt='Prévia da estrutura de evento';const meta=document.createElement('div');meta.className='party-image-meta';const caption=document.createElement('input');caption.type='text';caption.maxLength=120;caption.placeholder='Legenda da foto (opcional)';caption.value=item.caption||'';caption.setAttribute('aria-label',`Legenda da foto ${i+1}`);caption.addEventListener('input',()=>partyImages[i].caption=caption.value);const del=document.createElement('button');del.type='button';del.className='secondary';del.textContent='Remover foto';del.addEventListener('click',()=>{partyImages.splice(i,1);renderPartyImages()});meta.append(caption,del);card.append(img,meta);box.append(card)});$('#partyImagesCount').textContent=`${partyImages.length} de 20 fotos adicionadas.`}
const defaultCalculatorSettings={liters_per_person_hour:{moderado:0.25,medio:0.375,alto:0.5},other_drinks_reduction_percent:20,estimate_range_percent:10,cup_volume_ml:300};
function fillCalculatorSettings(){const s=partyContent.calculator_settings||defaultCalculatorSettings;$('#calcRateModerado').value=s.liters_per_person_hour?.moderado??defaultCalculatorSettings.liters_per_person_hour.moderado;$('#calcRateMedio').value=s.liters_per_person_hour?.medio??defaultCalculatorSettings.liters_per_person_hour.medio;$('#calcRateAlto').value=s.liters_per_person_hour?.alto??defaultCalculatorSettings.liters_per_person_hour.alto;$('#calcOtherDrinks').value=s.other_drinks_reduction_percent??defaultCalculatorSettings.other_drinks_reduction_percent;$('#calcRange').value=s.estimate_range_percent??defaultCalculatorSettings.estimate_range_percent;$('#calcCup').value=s.cup_volume_ml??defaultCalculatorSettings.cup_volume_ml}
function readCalculatorSettings(){const settings={liters_per_person_hour:{moderado:Number($('#calcRateModerado').value),medio:Number($('#calcRateMedio').value),alto:Number($('#calcRateAlto').value)},other_drinks_reduction_percent:Number($('#calcOtherDrinks').value),estimate_range_percent:Number($('#calcRange').value),cup_volume_ml:Number($('#calcCup').value)};if(!(settings.liters_per_person_hour.moderado>0&&settings.liters_per_person_hour.medio>=settings.liters_per_person_hour.moderado&&settings.liters_per_person_hour.alto>=settings.liters_per_person_hour.medio))throw new Error('Os consumos devem ser positivos e seguir a ordem moderado, médio e alto.');if(settings.other_drinks_reduction_percent<0||settings.other_drinks_reduction_percent>80)throw new Error('A redução para outras bebidas deve ficar entre 0% e 80%.');if(settings.estimate_range_percent<0||settings.estimate_range_percent>50)throw new Error('A margem de variação deve ficar entre 0% e 50%.');if(settings.cup_volume_ml<100||settings.cup_volume_ml>1000)throw new Error('O volume do copo deve ficar entre 100 ml e 1.000 ml.');return settings}
async function loadPartyContent(){const rows=await req('/rest/v1/party_event_content?select=id,included_items,images&limit=1');partyContent=rows?.[0]||{included_items:[],images:[],calculator_settings:defaultCalculatorSettings};try{const config=await req('/rest/v1/party_event_content?select=calculator_settings&limit=1');partyContent.calculator_settings=config?.[0]?.calculator_settings||defaultCalculatorSettings}catch(err){console.warn('Parâmetros novos da calculadora ainda não foram carregados. Os valores padrão serão exibidos; execute o SQL de Monte seu evento para salvar ajustes.',err);partyContent.calculator_settings=defaultCalculatorSettings}partyItems=Array.isArray(partyContent.included_items)?partyContent.included_items.map(x=>typeof x==='string'?x:x?.label||'').filter(Boolean):[];partyImages=Array.isArray(partyContent.images)?partyContent.images.filter(x=>x?.image_url).map(x=>({...x})):[];renderPartyItems();renderPartyImages();fillCalculatorSettings()}
$('#addPartyItem')?.addEventListener('click',()=>{partyItems.push('');renderPartyItems();$('#partyItemsEditor input:last-of-type')?.focus()});
$('#partyImagesInput')?.addEventListener('change',e=>{const files=[...(e.currentTarget.files||[])];const out=$('#partyContentMsg');try{if(partyImages.length+files.length>20)throw new Error('O limite é de 20 fotos. Remova alguma foto antes de adicionar mais.');for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error(`${file.name}: use JPG, PNG ou WEBP.`);if(file.size>5*1024*1024)throw new Error(`${file.name}: a imagem ultrapassa 5 MB.`)}files.forEach(file=>partyImages.push({file,preview:URL.createObjectURL(file),caption:''}));renderPartyImages();msg(out,'Fotos adicionadas. Clique em “Salvar informativos” para publicar.','success')}catch(err){msg(out,err.message,'error')}finally{e.currentTarget.value=''}});
async function uploadPartyImage(file){const ext=(file.name.split('.').pop()||'webp').toLowerCase();const path=`monte-evento-${Date.now()}-${Math.random().toString(36).slice(2,8)}.${ext}`;await req(`/storage/v1/object/event-images/${encodeURIComponent(path)}`,{method:'POST',body:file,headers:{'Content-Type':file.type,'x-upsert':'false'}});return `${URL}/storage/v1/object/public/event-images/${path}`}
$('#savePartyContent')?.addEventListener('click',async()=>{const out=$('#partyContentMsg');msg(out,'Salvando informativos e calculadora…');try{if(partyItems.length>30)throw new Error('O limite é de 30 itens inclusos.');const calculator_settings=readCalculatorSettings();const items=partyItems.map(x=>x.trim()).filter(Boolean);const images=[];for(const item of partyImages){const image_url=item.file?await uploadPartyImage(item.file):item.image_url;if(image_url)images.push({image_url,caption:(item.caption||'').trim()})}const body={id:'00000000-0000-4000-8000-000000000001',included_items:items,images,calculator_settings,updated_at:new Date().toISOString()};if(partyContent.id)await req(`/rest/v1/party_event_content?id=eq.${encodeURIComponent(partyContent.id)}`,{method:'PATCH',body,headers:{Prefer:'return=minimal'}});else await req('/rest/v1/party_event_content',{method:'POST',body,headers:{Prefer:'return=minimal'}});await loadPartyContent();msg(out,'Informativos, fotos e calculadora salvos no site.','success')}catch(err){const detail=String(err?.message||'');msg(out,/calculator_settings|PGRST204|column/i.test(detail)?'Execute o SQL supabase-monte-seu-evento.sql no Supabase para ativar o salvamento da calculadora.':detail||'Não foi possível salvar os informativos e a calculadora.','error')}});
async function loadSettings(){const rows=await req('/rest/v1/site_settings?select=*&limit=1');settingsRow=rows?.[0]||null;$('#setWhatsapp').value=settingsRow?.whatsapp||'';$('#setInstagram').value=settingsRow?.instagram||''}
$('#settingsForm').addEventListener('submit',async e=>{e.preventDefault();try{const body={whatsapp:$('#setWhatsapp').value.trim(),instagram:$('#setInstagram').value.trim()};if(settingsRow)await req(`/rest/v1/site_settings?id=eq.${settingsRow.id}`,{method:'PATCH',body,headers:{Prefer:'return=minimal'}});else await req('/rest/v1/site_settings',{method:'POST',body,headers:{Prefer:'return=minimal'}});await loadSettings();msg(appMsg,'Configurações salvas.','success')}catch(err){msg(appMsg,err.message,'error')}});
const dlg=$('#beerDialog');let editorMedia=[];function val(id,v=''){const e=$(id);if(e)e.value=v??''}
function normalizeMediaItem(item){if(!item)return null;if(typeof item==='string')return{url:item,type:/\.(mp4|webm|mov)(\?|$)/i.test(item)?'video':'image'};const url=item.url||item.src||'';if(!url)return null;return{url,type:item.type==='video'||String(item.mime||'').startsWith('video/')?'video':'image'}}
function mediaFromBeer(b){const list=Array.isArray(b?.media_urls)?b.media_urls.map(normalizeMediaItem).filter(Boolean):[];if(!list.length&&b?.image_url)list.push({url:b.image_url,type:'image'});return list}
function renderEditorMedia(){const box=$('#mediaPreviewList');if(!box)return;box.replaceChildren();if(!editorMedia.length){const p=document.createElement('p');p.className='muted';p.textContent='Nenhuma mídia adicionada.';box.append(p);return}editorMedia.forEach((m,i)=>{const item=document.createElement('div');item.className='media-item';const media=m.type==='video'?document.createElement('video'):document.createElement('img');media.src=m.preview||m.url;if(m.type==='video'){media.muted=true;media.playsInline=true;media.controls=true}else media.alt='Prévia da cerveja';const type=document.createElement('span');type.className='media-type';type.textContent=m.type==='video'?'VÍDEO':'IMAGEM';const controls=document.createElement('div');controls.className='media-item-controls';[['←',-1],['→',1]].forEach(([txt,dir])=>{const b=document.createElement('button');b.type='button';b.textContent=txt;b.disabled=(dir<0&&i===0)||(dir>0&&i===editorMedia.length-1);b.addEventListener('click',()=>{const j=i+dir;[editorMedia[i],editorMedia[j]]=[editorMedia[j],editorMedia[i]];renderEditorMedia()});controls.append(b)});const del=document.createElement('button');del.type='button';del.textContent='×';del.setAttribute('aria-label','Remover mídia');del.addEventListener('click',()=>{editorMedia.splice(i,1);renderEditorMedia()});controls.append(del);item.append(media,type,controls);box.append(item)})}
function syncPreLaunchFields(){const enabled=$('#fPreLaunch').checked;$('#prelaunchDateField').hidden=!enabled;if(!enabled)$('#fPickupDate').value=''}
$('#fPreLaunch').addEventListener('change',syncPreLaunchFields);
function openEditor(b=null){$('#beerForm').reset();$$('input[name=tag]').forEach(x=>x.checked=false);editorMedia=mediaFromBeer(b);renderEditorMedia();$('#deactivateBtn').hidden=!b;$('#editorTitle').textContent=b?'Editar cerveja':'Nova cerveja';val('#beerId',b?.id);val('#fBrand',b?.brand);val('#fName',b?.name);val('#fTitle',b?.title);val('#fSubtitle',b?.subtitle);val('#fStyle',b?.style);val('#fBrewery',b?.brewery);val('#fVolume',b?.volume);val('#fPrice',b?.price);val('#fAbv',b?.abv);val('#fIbu',b?.ibu);val('#fHops',b?.hops);val('#fSort',b?.sort_order??beers.length+1);val('#fIntensity',b?.intensity||'🟢 Leve');val('#fBitterness',b?.bitterness||'🟢 Muito baixo');val('#fStockQty',b?.stock_quantity);val('#fStock',b?.stock_status||'in_stock');$('#fActive').checked=b?.active!==false;$('#fFeatured').checked=b?.featured===true;$('#fPreLaunch').checked=b?.is_pre_launch===true;val('#fPickupDate',b?.pickup_date||'');syncPreLaunchFields();val('#fProfile',b?.profile);val('#fRecommendation',b?.recommendation);val('#fDescription',b?.description);msg($('#editorMsg'),'');msg($('#mediaSelectionMsg'),'');dlg.showModal();if(b)loadTags(b.id)}
async function loadTags(id){try{const tags=await req(`/rest/v1/beer_tags?beer_id=eq.${encodeURIComponent(id)}&select=tag`);const set=new Set(tags.map(t=>t.tag));$$('input[name=tag]').forEach(x=>x.checked=set.has(x.value))}catch(err){msg($('#editorMsg'),err.message,'error')}}
$('#newBeerBtn').addEventListener('click',()=>openEditor());$('#newBeerTop').addEventListener('click',()=>openEditor());$('#closeDialog').addEventListener('click',()=>dlg.close());dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close()});
function filePreview(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('Não foi possível ler '+file.name+'. Tente salvar a imagem como JPG, PNG ou WEBP.'));reader.readAsDataURL(file)})}
$('#fMedia').addEventListener('change',async e=>{const input=e.currentTarget;const files=[...(input.files||[])];const out=$('#mediaSelectionMsg');if(!files.length)return msg(out,'Nenhum arquivo foi selecionado.','error');msg(out,`Carregando ${files.length} arquivo${files.length>1?'s':''}…`);try{const added=[];for(const file of files){const isVideo=file.type.startsWith('video/');const isImage=file.type.startsWith('image/');if(!isVideo&&!isImage)throw new Error(`${file.name}: formato não reconhecido como imagem ou vídeo.`);const limit=isVideo?40*1024*1024:5*1024*1024;if(file.size>limit)throw new Error(`${file.name}: ${isVideo?'o vídeo ultrapassa 40 MB':'a imagem ultrapassa 5 MB'}.`);let preview='';if(isImage)preview=await filePreview(file);else preview=URL.createObjectURL(file);added.push({type:isVideo?'video':'image',file,preview,url:''})}const newImages=added.filter(m=>m.type==='image');const newVideos=added.filter(m=>m.type==='video');if(newImages.length)editorMedia=[...newImages,...editorMedia,...newVideos];else editorMedia.push(...newVideos);renderEditorMedia();msg(out,`${files.length} arquivo${files.length>1?'s carregados':' carregado'} para prévia. Clique em Salvar para enviar ao site.`,'success')}catch(err){msg(out,err.message||'Não foi possível carregar o arquivo.','error')}finally{input.value=''}});
async function uploadMedia(file,slug){if(!file)return null;const isVideo=file.type.startsWith('video/');const limit=isVideo?40*1024*1024:5*1024*1024;if(file.size>limit)throw new Error(isVideo?'O vídeo ultrapassa 40 MB.':'A imagem ultrapassa 5 MB.');const ext=(file.name.split('.').pop()||(isVideo?'mp4':'webp')).toLowerCase();const path=`${slug}-${Date.now()}-${Math.random().toString(36).slice(2,7)}.${ext}`;await req(`/storage/v1/object/beer-images/${encodeURIComponent(path)}`,{method:'POST',body:file,headers:{'Content-Type':file.type||'application/octet-stream','x-upsert':'false'}});return `${URL}/storage/v1/object/public/beer-images/${path}`}
function slugifyBeer(value){return String(value||'cerveja').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80)||'cerveja'}
function availableBeerSlug(base,ignoreId=null){const root=slugifyBeer(base);let candidate=root,n=2;const used=new Set(beers.filter(b=>b.id!==ignoreId).map(b=>String(b.slug||'').toLowerCase()));while(used.has(candidate.toLowerCase()))candidate=`${root}-${n++}`;return candidate}
$('#beerForm').addEventListener('submit',async e=>{e.preventDefault();const out=$('#editorMsg');msg(out,'Salvando…');try{const existingId=$('#beerId').value||null;const existing=existingId?beers.find(b=>b.id===existingId):null;if($('#fPreLaunch').checked&&!$('#fPickupDate').value)throw new Error('Informe a data para retirada do pré-lançamento.');if($('#fFeatured').checked&&$('#fActive').checked){const selected=await req('/rest/v1/beers?select=id&featured=eq.true&active=eq.true');if(selected.filter(b=>b.id!==existingId).length>=8)throw new Error('A geladeira comporta 8 rótulos. Desmarque outro rótulo antes de adicionar este.');}const name=$('#fName').value.trim();const title=name;const slug=existing?.slug||availableBeerSlug(title||name,existingId);const uploaded=[];for(const m of editorMedia){let url=m.url;if(m.file)url=await uploadMedia(m.file,slug);if(url)uploaded.push({url,type:m.type})}const cover=uploaded[0]||null;const image=(cover?.type==='image'?cover:uploaded.find(m=>m.type==='image'))?.url||null;const body={slug,brand:$('#fBrewery').value.trim(),name,title,subtitle:$('#fStyle').value.trim(),style:$('#fStyle').value.trim(),brewery:$('#fBrewery').value.trim(),volume:$('#fVolume').value.trim(),price:$('#fPrice').value===''?null:Number($('#fPrice').value),abv:$('#fAbv').value.trim(),ibu:existing?.ibu||'',hops:existing?.hops||'',description:existing?.description||'',intensity:existing?.intensity||'',bitterness:existing?.bitterness||'',profile:existing?.profile||'',recommendation:existing?.recommendation||'',image_url:image,media_urls:uploaded,image_alt:title||name,signal:Number(existing?.signal)||0,featured:$('#fFeatured').checked,active:$('#fActive').checked,stock_quantity:$('#fStockQty').value===''?null:Number($('#fStockQty').value),stock_status:$('#fStock').value,sort_order:Number($('#fSort').value)||0,order_name:title||name,is_pre_launch:$('#fPreLaunch').checked,pickup_date:$('#fPreLaunch').checked?($('#fPickupDate').value||null):null};let beerId=existingId;if(existingId)await req(`/rest/v1/beers?id=eq.${encodeURIComponent(existingId)}`,{method:'PATCH',body,headers:{Prefer:'return=minimal'}});else{const created=await req('/rest/v1/beers',{method:'POST',body,headers:{Prefer:'return=representation'}});beerId=created[0].id}await req(`/rest/v1/beer_tags?beer_id=eq.${encodeURIComponent(beerId)}`,{method:'DELETE'});const tags=$$('input[name=tag]:checked').map(x=>({beer_id:beerId,tag:x.value}));if(tags.length)await req('/rest/v1/beer_tags',{method:'POST',body:tags,headers:{Prefer:'return=minimal'}});await loadBeers();msg(out,'Cerveja salva e catálogo atualizado.','success');setTimeout(()=>dlg.close(),650)}catch(err){msg(out,err.message,'error')}});
$('#deactivateBtn').addEventListener('click',async()=>{const id=$('#beerId').value;if(!id)return;try{await req(`/rest/v1/beers?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:{active:false},headers:{Prefer:'return=minimal'}});await loadBeers();dlg.close();msg(appMsg,'Cerveja desativada.','success')}catch(err){msg($('#editorMsg'),err.message,'error')}});
(async()=>{try{const raw=localStorage.getItem('cd_admin_session');if(!raw)return;session=JSON.parse(raw);if(!session?.access_token)return clearSession();if(session.expires_at&&Date.now()/1000>session.expires_at-30)await refresh();await enter()}catch{clearSession()}})();
